param([switch]$Check)

$ErrorActionPreference = 'Stop'
$sqlDirectory = Join-Path $PSScriptRoot '../backend/RoomRental.BackEnd/SQL'
$output = Join-Path $sqlDirectory '10_Deploy_ApprovedModules.sql'
$header = @'
-- RoomRentalSystem: approved additive upgrades 07 -> 08 -> 09.
-- Generated by tools/New-ModuleUpgradeSql.ps1. Run the WHOLE file in SSMS.
-- BACK UP FIRST. Stop the API/worker while deploying. Select the database explicitly.
-- On RoomRentalDB only, change the following 0 to 1 after backup/review.
-- No existing business rows or columns are changed. No sample data is inserted.
SET NOCOUNT ON;
SET XACT_ABORT ON;
SET ANSI_NULLS ON; SET ANSI_PADDING ON; SET ANSI_WARNINGS ON; SET ARITHABORT ON;
SET CONCAT_NULL_YIELDS_NULL ON; SET QUOTED_IDENTIFIER ON; SET NUMERIC_ROUNDABORT OFF;
DECLARE @AllowMainDatabase bit = 0;
IF DB_NAME() = N'RoomRentalDB' AND @AllowMainDatabase <> 1
    THROW 51100, 'Back up RoomRentalDB, then explicitly set @AllowMainDatabase = 1.', 1;
IF DB_NAME() <> N'RoomRentalDB' AND DB_NAME() NOT LIKE N'RoomRental[_]Verification[_]%'
    THROW 51101, 'Wrong database. Select RoomRentalDB or a RoomRental_Verification_* QA database.', 1;
IF @@TRANCOUNT <> 0
    THROW 51102, 'Run this script outside any existing transaction.', 1;
IF SCHEMA_NAME() <> N'dbo'
    THROW 51103, 'Use a deployment account whose default schema is dbo.', 1;
IF TRY_CONVERT(int, SERVERPROPERTY('ProductMajorVersion')) < 14
    THROW 51104, 'SQL Server 2017 or later is required.', 1;
IF (SELECT compatibility_level FROM sys.databases WHERE name=DB_NAME()) < 130
    THROW 51105, 'Database compatibility level must be at least 130. Review separately; not changed automatically.', 1;
DECLARE @BaseTables TABLE(Name sysname PRIMARY KEY);
INSERT @BaseTables VALUES (N'TaiKhoan'),(N'PhongTro'),(N'HopDongThue'),(N'DatCoc'),(N'GiaoDichThanhToan'),(N'HoaDonHangThang');
IF EXISTS(SELECT 1 FROM @BaseTables WHERE OBJECT_ID(N'dbo.'+Name,N'U') IS NULL)
    THROW 51106, 'Missing base tables. This is an upgrade, not a new-database installer.', 1;

BEGIN TRY
    BEGIN TRANSACTION;
    DECLARE @BundleLock int;
    EXEC @BundleLock = sys.sp_getapplock @Resource=N'RoomRental.Schema.ApprovedModules',
        @LockMode=N'Exclusive', @LockOwner=N'Transaction', @LockTimeout=10000;
    IF @BundleLock < 0 THROW 51107, 'Another schema upgrade is running. Retry later.', 1;

'@

$parts = @($header)
foreach ($file in @('07_RoommateModule.sql', '08_PaymentSafety.sql', '09_ContractClosure.sql')) {
    $sql = [IO.File]::ReadAllText((Join-Path $sqlDirectory $file)).Replace("`r`n", "`n")
    if ($file -eq '07_RoommateModule.sql') {
        $old = "IF DB_NAME() NOT LIKE N'RoomRental[_]Verification[_]%'"
        if ($sql.Split([string[]]@($old), [StringSplitOptions]::None).Length -ne 2) {
            throw 'Version 07 guard changed. Review the bundle generator.'
        }
        $sql = $sql.Replace($old, "IF DB_NAME() <> N'RoomRentalDB' AND DB_NAME() NOT LIKE N'RoomRental[_]Verification[_]%'")
        $sql = $sql.Replace('-- Version 07: additive Roommate module. QA only until deployment is reviewed.',
            '-- Version 07: reviewed bundle; main opt-in is enforced by the outer batch.')
    }
    else {
        $pattern = 'DECLARE @AllowMainDatabase bit\s*=\s*0;'
        if ([regex]::Matches($sql, $pattern).Count -ne 1) {
            throw "$file opt-in changed. Review the bundle generator."
        }
        # Inner batches only run after the outer explicit main-database guard passes.
        $sql = [regex]::Replace($sql, $pattern, 'DECLARE @AllowMainDatabase bit = 1; -- Outer batch already authorized this database.')
    }
    $parts += "    -- BEGIN $file`n    EXEC sys.sp_executesql N'" + $sql.Replace("'", "''").TrimEnd() + "';`n    -- END $file`n"
}
$parts += @'
    IF @@TRANCOUNT <> 1 THROW 51108, 'Unexpected transaction state. Upgrade cannot commit.', 1;
    COMMIT TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    THROW;
END CATCH;

-- Only this final message means ALL three upgrades committed successfully.
PRINT 'SUCCESS: approved modules 07/08/09 committed. Existing business rows unchanged.';
SELECT DB_NAME() AS DatabaseName, t.name AS TableName, COUNT(c.column_id) AS ColumnCount
FROM sys.tables t JOIN sys.columns c ON c.object_id=t.object_id
WHERE t.schema_id=SCHEMA_ID(N'dbo') AND t.name IN (
    N'TinTimNguoiOGhep',N'YeuCauOGhep',N'NguoiOCungHopDong',
    N'SuKienThanhToan',N'YeuCauHoanCoc',N'HoSoKetThucHopDong',
    N'YeuCauKetThucHopDong',N'PhuongAnTatToanHopDong',
    N'KhoanMucTatToanHopDong',N'LichSuKetThucHopDong')
GROUP BY t.name ORDER BY t.name;
'@
$result = ($parts -join "`n").Replace("`r`n", "`n") + "`n"
if ($Check) {
    if (!(Test-Path -LiteralPath $output) -or [IO.File]::ReadAllText($output).Replace("`r`n", "`n") -cne $result) {
        throw 'The SQL bundle is missing or out of date. Regenerate it before deployment.'
    }
    Write-Output 'SQL bundle matches source scripts 07/08/09.'
}
else {
    [IO.File]::WriteAllText($output, $result, [Text.UTF8Encoding]::new($false))
    Write-Output $output
}
